
"use strict";

document.querySelector(".formula").textContent="dxᵢ/dt = rᵢxᵢ(1 − xᵢ + Σⱼ≠ᵢ aᵢⱼxⱼ) − mᵢxᵢ + Dᵢ";
document.querySelector(".version").textContent="v3.4";
const dispersalOption=document.createElement("option");
dispersalOption.value="d";dispersalOption.textContent="迁入率 D";
document.getElementById("target").insertBefore(dispersalOption,document.querySelector('#target option[value="a"]'));
document.querySelectorAll("#fitPanel .fit-note")[0].innerHTML='<b>拟合依据：</b>死亡率作为独立损失项 −mᵢxᵢ。单培养用 B₀、B(tₘ)、K 和独立测得的 m 数值求解增长率 r；两两共培养稳定终点用于计算 aᵢⱼ。中间测量时刻 tₘ：<input id="midTime" type="number" value="4" min="0.01"> h';
document.querySelectorAll("#fitPanel .fit-note")[1].innerHTML='<b>实验参数说明：</b><br><b>B₀</b>：培养开始时的实际生物量，单位与 K 相同。<br><b>B(tₘ)</b>：单培养至 tₘ 时的实际生物量，用于拟合 r。<br><b>tₘ</b>：测量 B(tₘ) 的培养时间，单位为 h。<br><b>m</b>：独立测得的死亡率，单位为 h⁻¹；死亡项仅为 −mx。<br><b>K</b>：无死亡时的基准环境容纳量，也是无量纲化尺度，B=Kx；有死亡时单培养稳定生物量为 K(1−m/r)。<br><b>r</b>：增长项的内禀增长率，单位为 h⁻¹，要求 r&gt;m。<br><b>D</b>：外部物种库持续迁入产生的加性输入，单位为归一化生物量·h⁻¹；设为 0 时恢复无迁入模型。实验拟合按 D=0 估计 r 与 a，拟合后可在结果参数表中设置 D。<br><b>Cᵢⱼ</b>：物种 i 与 j 两两共培养时，物种 i 的稳定终点实际生物量。<br><b>aᵢⱼ</b>：物种 j 对物种 i 的无量纲作用强度；正值为促进，负值为抑制。';
document.querySelector("#fitResultPanel .subhead span").textContent="B₀、r、m、K 和 D";
document.querySelector("#fitPanel section .subhead span").textContent="输入 B₀、B(tₘ)、m 与基准 K";
document.querySelector(".method").innerHTML='稳定判据：max |dxᵢ/dt| / max(1,x) &lt; <input id="tol" type="number" value="0.0001" step="0.00001" style="width:90px">　·　Bᵢ = Kᵢxᵢ　·　死亡项 = −mᵢxᵢ　·　迁入项 = +Dᵢ';
const colors=["#d86d5b","#173f67","#c49a45","#73866b","#4d8c8a","#8d6d9f","#b85c86","#607d9d","#9b7048","#526b4f"];
const $=id=>document.getElementById(id),clamp=(v,l,h)=>Math.max(l,Math.min(h,v)),num=(id)=>Number($(id).value),fmt=(v,d=3)=>Number.isFinite(v)?v.toLocaleString("zh-CN",{maximumFractionDigits:d}):"—";
let N=5,mode="known",species=[],A=[],pairs=[],result=null,fitReady=false;
function gauss(){let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function makeSpecies(n){return Array.from({length:n},(_,i)=>({name:`Species ${i+1}`,b0:+Math.max(.02,.1-i*.008).toFixed(3),g:+(.55+i%4*.1).toFixed(3),m:+(.04+i%3*.01).toFixed(3),k:+(.8+i%3*.2).toFixed(3),d:0,bMid:+(.45+i%3*.08).toFixed(3)}))}
function makeA(n){return Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>{if(i===j)return-1;let z=Math.sin((i+1)*12.9898+(j+1)*78.233)*43758.5453;return+(((z-Math.floor(z))-.5)*.36).toFixed(3)}))}
function makePairs(){return species.map((si,i)=>species.map((sj,j)=>{let ci=Math.max(0,1-si.m/si.g),cj=Math.max(0,1-sj.m/sj.g);if(i===j)return+(ci*si.k).toFixed(3);let den=1-A[i][j]*A[j][i],x=Math.abs(den)<1e-8?.5:Math.max(.02,(ci+A[i][j]*cj)/den);return+(x*si.k).toFixed(3)}))}
function sync(){let root=mode==="known"?$("knownPanel"):$("fitPanel");if(mode==="known"){root.querySelectorAll("[data-s]").forEach(el=>{let i=+el.dataset.s,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)});root.querySelectorAll("[data-a]").forEach(el=>{let [i,j]=el.dataset.a.split(",").map(Number);if(i!==j&&A[i]&&j<A[i].length)A[i][j]=Number(el.value)})}else{root.querySelectorAll("[data-exp]").forEach(el=>{let i=+el.dataset.exp,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)});root.querySelectorAll("[data-p]").forEach(el=>{let [i,j]=el.dataset.p.split(",").map(Number);if(i!==j&&pairs[i]&&j<pairs[i].length)pairs[i][j]=Number(el.value)});if(fitReady){root.querySelectorAll("[data-frs]").forEach(el=>{let i=+el.dataset.frs,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)});root.querySelectorAll("[data-fra]").forEach(el=>{let [i,j]=el.dataset.fra.split(",").map(Number);if(i!==j&&A[i]&&j<A[i].length)A[i][j]=Number(el.value)})}}}
function validate(){if(!Number.isFinite(num("tMax"))||num("tMax")<=0)throw Error("模拟时长必须大于 0");if(!Number.isFinite(num("sample"))||num("sample")<=0)throw Error("采样间隔必须大于 0");species.forEach((s,i)=>{if(!s.name.trim())s.name=`Species ${i+1}`;if(!Number.isFinite(s.b0)||s.b0<0)throw Error(`${s.name} 的初始生物量必须为非负数`);if(!Number.isFinite(s.g)||s.g<=0)throw Error(`${s.name} 的增长率 r 必须大于 0`);if(!Number.isFinite(s.m)||s.m<0)throw Error(`${s.name} 的死亡率 m 必须为非负数`);if(s.g<=s.m)throw Error(`${s.name} 必须满足增长率 r > 死亡率 m`);if(!Number.isFinite(s.k)||s.k<=0)throw Error(`${s.name} 的容纳量必须大于 0`);if(!Number.isFinite(s.d)||s.d<0)throw Error(`${s.name} 的迁入率 D 必须为非负数`)});A.forEach((r,i)=>r.forEach((v,j)=>{if(!Number.isFinite(v))throw Error(`相互作用系数 a${i+1}${j+1} 不是有效数字`)}))}
function speciesHTML(fit=false,resultTable=false){let attr=fit?"data-exp":resultTable?"data-frs":"data-s";return `<table><thead><tr><th>物种</th><th>初始 B₀</th>${fit?"<th>B(tₘ)</th>":""}<th>${fit?"拟合增长率 r":"增长率 r"}</th><th>死亡率 m</th><th>容纳量 K</th>${fit?"":"<th>迁入率 D</th>"}</tr></thead><tbody>${species.map((s,i)=>`<tr><td class="name"><input ${attr}="${i}" data-key="name" value="${s.name}"></td><td><input type="number" ${attr}="${i}" data-key="b0" value="${s.b0}" step=".01"></td>${fit?`<td><input type="number" ${attr}="${i}" data-key="bMid" value="${s.bMid}" step=".01"></td>`:""}<td><input type="number" ${attr}="${i}" data-key="g" value="${s.g}" step=".01" ${fit?"readonly":""}></td><td><input type="number" ${attr}="${i}" data-key="m" value="${s.m}" min="0" step=".01"></td><td><input type="number" ${attr}="${i}" data-key="k" value="${s.k}" step=".1"></td>${fit?"":`<td><input type="number" ${attr}="${i}" data-key="d" value="${s.d??0}" min="0" step="0.000001"></td>`}</tr>`).join("")}</tbody></table>`}
function matrixHTML(resultTable=false){let attr=resultTable?"data-fra":"data-a";return `<table class="matrix"><thead><tr><th></th>${species.map((_,i)=>`<th>S${i+1}</th>`).join("")}</tr></thead><tbody>${A.map((r,i)=>`<tr><th>S${i+1}</th>${r.map((v,j)=>{let bg=i===j?"#ead8cf":v>0?`rgba(23,63,103,${.08+Math.min(.75,Math.abs(v))*.5})`:`rgba(216,109,91,${.08+Math.min(.75,Math.abs(v))*.5})`;return`<td style="background:${bg}"><input type="number" ${attr}="${i},${j}" value="${v}" step=".01" ${i===j?"readonly":""}></td>`}).join("")}</tr>`).join("")}</tbody></table>`}
function pairHTML(){return `<table><thead><tr><th>响应物种</th>${species.map((_,i)=>`<th>与 S${i+1}</th>`).join("")}</tr></thead><tbody>${pairs.map((r,i)=>`<tr><th>S${i+1}</th>${r.map((v,j)=>`<td class="${i===j?"diag":""}"><input type="number" data-p="${i},${j}" value="${i===j?+(species[i].k*(1-species[i].m/species[i].g)).toFixed(3):v}" step=".01" ${i===j?"readonly":""}></td>`).join("")}</tr>`).join("")}</tbody></table>`}
function renderInputs(){$("speciesTable").innerHTML=speciesHTML();$("matrixTable").innerHTML=matrixHTML();$("fitSpeciesTable").innerHTML=speciesHTML(true);$("pairTable").innerHTML=pairHTML();$("fitResultSpecies").innerHTML=speciesHTML(false,true);$("fitResultMatrix").innerHTML=matrixHTML(true);$("fitResultPanel").classList.toggle("hidden",!fitReady)}
function deriv(x){return x.map((xi,i)=>{let b=1;for(let j=0;j<N;j++)b+=A[i][j]*x[j];return species[i].g*xi*b-species[i].m*xi+(species[i].d??0)})}
function rk4(x,h){let k1=deriv(x),k2=deriv(x.map((v,i)=>v+h*k1[i]/2)),k3=deriv(x.map((v,i)=>v+h*k2[i]/2)),k4=deriv(x.map((v,i)=>v+h*k3[i]));return x.map((v,i)=>clamp(v+h*(k1[i]+2*k2[i]+2*k3[i]+k4[i])/6,0,1e6))}
function simulate(){sync();validate();let tm=Math.max(1,num("tMax")),sample=Math.max(.05,num("sample")),tol=Math.max(1e-8,num("tol")),x=species.map(s=>Math.max(0,s.b0/s.k)),h=Math.max(.0005,Math.min(.05,sample/5,tm/3000)),t=0,next=sample,pts=[{t:0,b:x.map((v,i)=>v*species[i].k)}],stableStart=null,stableTime=null,window=Math.max(sample*3,Math.min(10,tm*.1)),warning="";while(t<tm-1e-10){let step=Math.min(h,tm-t);x=rk4(x,step);t+=step;if(x.some(v=>!Number.isFinite(v)||v>=999999)){warning="系统出现无界增长：请减弱正相互作用或降低初始生物量";break}let d=deriv(x),ok=Math.max(...d.map(Math.abs))/Math.max(1,...x)<tol;if(ok){if(stableStart===null)stableStart=t;if(stableTime===null&&t-stableStart>=window)stableTime=stableStart}else stableStart=null;if(t+1e-8>=next||t+1e-8>=tm){pts.push({t:Math.min(t,tm),b:x.map((v,i)=>v*species[i].k)});next+=sample}}let end=x.map((v,i)=>v*species[i].k),sum=end.reduce((a,b)=>a+b,0),rel=end.map(v=>sum?v/sum:0);result={pts,end,rel,stableTime,warning};draw();setStatus(warning||"模拟完成")}
function color(i){return colors[i%colors.length]}
function draw(){if(!result)return;drawLine();drawDonut();$("stableTime").textContent=result.stableTime===null?"未达到":fmt(result.stableTime,2)+" h";$("legend").innerHTML=species.map((s,i)=>`<span><i style="background:${color(i)}"></i>${s.name}</span>`).join("");$("donutList").innerHTML=species.map((s,i)=>`<div><span><i style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${color(i)};margin-right:4px"></i>${s.name}</span><b>${fmt(result.rel[i]*100,1)}%</b></div>`).join("");let mx=Math.max(...result.end,.01);$("bars").innerHTML=species.map((s,i)=>`<div class="bar"><span>${s.name}</span><div class="track"><i style="width:${Math.max(.5,result.end[i]/mx*100)}%;background:${color(i)}"></i></div><b>${fmt(result.end[i],4)}</b></div>`).join("")}
function drawLine(){let c=$("lineChart"),ctx=c.getContext("2d"),W=c.width,H=c.height,p={l:52,r:16,t:14,b:35},last=result.pts[result.pts.length-1],maxT=Math.max(1,last.t),maxB=Math.max(.1,...result.pts.flatMap(q=>q.b))*1.08,X=t=>p.l+t/maxT*(W-p.l-p.r),Y=v=>H-p.b-v/maxB*(H-p.t-p.b);ctx.clearRect(0,0,W,H);ctx.font="10px Arial";ctx.fillStyle="#666";ctx.strokeStyle="#ddd6ca";ctx.lineWidth=1;for(let k=0;k<5;k++){let v=maxB*k/4,y=Y(v);ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(p.l,y);ctx.lineTo(W-p.r,y);ctx.stroke();ctx.fillText(fmt(v,2),5,y+3)}for(let k=0;k<6;k++){let v=maxT*k/5;ctx.fillText(fmt(v,1),X(v)-8,H-12)}ctx.setLineDash([]);species.forEach((s,i)=>{ctx.strokeStyle=color(i);ctx.lineWidth=2.2;ctx.beginPath();result.pts.forEach((q,k)=>k?ctx.lineTo(X(q.t),Y(q.b[i])):ctx.moveTo(X(q.t),Y(q.b[i])));ctx.stroke()});if(result.stableTime!==null){ctx.strokeStyle="#d86d5b";ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(X(result.stableTime),p.t);ctx.lineTo(X(result.stableTime),H-p.b);ctx.stroke();ctx.setLineDash([])}}
function drawDonut(){let c=$("donut"),ctx=c.getContext("2d"),cx=110,cy=110,a=-Math.PI/2;ctx.clearRect(0,0,220,220);result.rel.forEach((v,i)=>{ctx.beginPath();ctx.arc(cx,cy,78,a,a+2*Math.PI*v);ctx.arc(cx,cy,43,a+2*Math.PI*v,a,true);ctx.closePath();ctx.fillStyle=color(i);ctx.fill();a+=2*Math.PI*v});ctx.fillStyle="#17324d";ctx.textAlign="center";ctx.font="bold 17px Georgia";ctx.fillText("100%",cx,cy-1);ctx.font="10px Arial";ctx.fillText("群落组成",cx,cy+17)}
function sampleDist(d,c,s,lo,hi){if(d==="constant")return c;if(d==="uniform")return lo+Math.random()*(hi-lo);if(d==="lognormal"){s=Math.max(.001,s);let mu=Math.log(Math.max(c,1e-9))-.5*s*s;return clamp(Math.exp(mu+s*gauss()),lo,hi)}return clamp(c+Math.max(0,s)*gauss(),lo,hi)}
function randomize(){sync();let target=$("target").value,d=$("dist").value,c=num("center"),s=num("spread"),lo=num("minVal"),hi=num("maxVal"),pct=num("posPct");if(d==="direct"){setStatus("直接输入模式：请在下方参数表格中填写数值");return}if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo>=hi)throw Error("分布下限必须小于上限");if(target==="a")A=A.map((r,i)=>r.map((v,j)=>{if(i===j)return-1;if(d==="mixed"){let sign=Math.random()*100<pct?1:-1,mag=sampleDist("normal",Math.abs(c)||.18,s,Math.max(0,lo),Math.max(0,hi));return+(sign*Math.abs(mag)).toFixed(3)}return+sampleDist(d,c,s,lo,hi).toFixed(3)}));else{let floor=target==="b0"||target==="m"||target==="d"?0:.0001;species=species.map(q=>({...q,[target]:+Math.max(floor,sampleDist(d,c,s,Math.max(floor,lo),Math.max(floor+.000001,hi))).toFixed(8)}))}renderInputs();setStatus("已按所选分布生成并回填参数")}
function batchSettings(){let target=$("target").value,d=$("dist").value,c=num("center"),s=num("spread"),lo=num("minVal"),hi=num("maxVal"),pct=num("posPct");if(d==="direct")throw Error("多次随机模拟需要先为目标参数选择一种随机分布");if(!Number.isFinite(lo)||!Number.isFinite(hi)||lo>=hi)throw Error("分布下限必须小于上限");if(!Number.isFinite(s)||s<0)throw Error("标准差必须为非负数");if(d==="mixed"&&(!Number.isFinite(pct)||pct<0||pct>100))throw Error("促进作用比例必须为 0–100% ");return{target,d,c,s,lo,hi,pct}}
function sampledModel(cfg){let sp=species.map(q=>({...q})),mat=A.map(r=>r.slice()),drawValue=()=>sampleDist(cfg.d,cfg.c,cfg.s,cfg.lo,cfg.hi);if(cfg.target==="a")mat=mat.map((r,i)=>r.map((v,j)=>{if(i===j)return-1;if(cfg.d==="mixed"){let sign=Math.random()*100<cfg.pct?1:-1,mag=sampleDist("normal",Math.abs(cfg.c)||.18,cfg.s,Math.max(0,cfg.lo),Math.max(0,cfg.hi));return sign*Math.abs(mag)}return drawValue()}));else sp=sp.map(q=>{let value,tries=0;do{value=drawValue();tries++}while(tries<200&&((cfg.target==="g"&&value<=q.m)||(cfg.target==="m"&&value>=q.g)));if(cfg.target==="b0"||cfg.target==="m"||cfg.target==="d")value=Math.max(0,value);else value=Math.max(.0001,value);if((cfg.target==="g"&&value<=q.m)||(cfg.target==="m"&&value>=q.g))throw Error("当前分布难以满足 r > m，请调整分布范围");return{...q,[cfg.target]:value}});return{sp,mat}}
function simulateModel(sp,mat){let tm=Math.max(1,num("tMax")),sample=Math.max(.05,num("sample")),tol=Math.max(1e-8,num("tol")),x=sp.map(s=>Math.max(0,s.b0/s.k)),h=Math.max(.0005,Math.min(.05,sample/5,tm/3000)),t=0,next=sample,pts=[{t:0,b:x.map((v,i)=>v*sp[i].k)}],stableStart=null,stableTime=null,window=Math.max(sample*3,Math.min(10,tm*.1)),warning="";let derivative=y=>y.map((yi,i)=>{let z=1;for(let j=0;j<N;j++)z+=mat[i][j]*y[j];return sp[i].g*yi*z-sp[i].m*yi+(sp[i].d??0)}),stepRK=(y,dt)=>{let k1=derivative(y),k2=derivative(y.map((v,i)=>v+dt*k1[i]/2)),k3=derivative(y.map((v,i)=>v+dt*k2[i]/2)),k4=derivative(y.map((v,i)=>v+dt*k3[i]));return y.map((v,i)=>clamp(v+dt*(k1[i]+2*k2[i]+2*k3[i]+k4[i])/6,0,1e6))};while(t<tm-1e-10){let step=Math.min(h,tm-t);x=stepRK(x,step);t+=step;if(x.some(v=>!Number.isFinite(v)||v>=999999)){warning="unbounded";break}let d=derivative(x),ok=Math.max(...d.map(Math.abs))/Math.max(1,...x)<tol;if(ok){if(stableStart===null)stableStart=t;if(stableTime===null&&t-stableStart>=window)stableTime=stableStart}else stableStart=null;if(t+1e-8>=next||t+1e-8>=tm){pts.push({t:Math.min(t,tm),b:x.map((v,i)=>v*sp[i].k)});next+=sample}}return{pts,stableTime,warning}}
function csvCell(v){let s=String(v==null?"":v);return/[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
async function saveCSV(text,name){let blob=new Blob(["\ufeff"+text],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.style.display="none";document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url)},1000);return"文件已提交到浏览器下载目录"}
async function runBatch(){if(mode!=="known")throw Error("请切换到“已知模型参数”页面运行多次随机模拟");resizeModel(false);sync();validate();let cfg=batchSettings(),count=Math.round(num("batchCount"));if(!Number.isFinite(count)||count<2||count>1000)throw Error("随机模拟次数必须为 2–1000 的整数");let button=$("batchBtn"),progress=$("batchProgress"),summary=$("batchSummary"),records=[],unbounded=0,seen=new Set(),signature=model=>cfg.target==="a"?model.mat.flat().map(v=>Number(v).toPrecision(12)).join("|"):model.sp.map(s=>Number(s[cfg.target]).toPrecision(12)).join("|");button.disabled=true;button.textContent="模拟中…";try{for(let run=1;run<=count;run++){let model,key,attempt=0;do{model=sampledModel(cfg);key=signature(model);attempt++}while(seen.has(key)&&attempt<100);if(seen.has(key))throw Error("当前分布产生了相同参数组；请增大标准差或取值范围后重试");seen.add(key);let sim=simulateModel(model.sp,model.mat),param=[];model.sp.forEach((s,i)=>param.push([`S${i+1}_name`,s.name],[`S${i+1}_B0`,s.b0],[`S${i+1}_r`,s.g],[`S${i+1}_m`,s.m],[`S${i+1}_K`,s.k],[`S${i+1}_D`,s.d??0]));for(let i=0;i<N;i++)for(let j=0;j<N;j++)param.push([`a${i+1}_${j+1}`,model.mat[i][j]]);if(sim.warning)unbounded++;records.push({run,sim,param});progress.style.width=(run/count*100)+"%";summary.textContent=`正在模拟：${run} / ${count}`;if(run%5===0)await new Promise(resolve=>setTimeout(resolve,0))}let paramNames=records[0].param.map(q=>q[0]),head=["run","status","stable_time","time",...species.map((s,i)=>`S${i+1}_${s.name}_B`),...paramNames],rows=[head.map(csvCell).join(",")];records.forEach(rec=>rec.sim.pts.forEach(pt=>rows.push([rec.run,rec.sim.warning||"ok",rec.sim.stableTime==null?"":rec.sim.stableTime,pt.t,...pt.b,...rec.param.map(q=>q[1])].map(csvCell).join(","))));let stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19),message=await saveCSV(rows.join("\n"),`glv_random_simulations_${count}_${stamp}.csv`);summary.textContent=`完成 ${count} 次模拟（无界增长 ${unbounded} 次）；${message}`;setStatus(`多次随机模拟完成：${count} 次，CSV 已生成`)}finally{button.disabled=false;button.textContent="运行并保存 CSV"}}
const targetInfo={b0:{name:"初始生物量 B₀",meaning:"模拟起始时物种的实际生物量；必须 ≥ 0，单位应与 K 一致。",defaults:[.08,.02,.01,.2]},g:{name:"增长率 r",meaning:"增长项的内禀增长率，单位为时间⁻¹；必须大于死亡率 m。",defaults:[.6,.1,.1,1.2]},m:{name:"死亡率 m",meaning:"独立损失项 −mᵢxᵢ 的死亡率，单位为时间⁻¹；不乘相互作用项，且须满足 0 ≤ m < r。",defaults:[.05,.015,0,.15]},k:{name:"基准环境容纳量 K",meaning:"无死亡时的单培养容纳量及无量纲化尺度；有死亡时单培养稳定生物量为 K(1−m/r)。",defaults:[1,.2,.2,2]},d:{name:"迁入率 D",meaning:"外部物种库对各物种的持续加性输入，单位为归一化生物量·时间⁻¹；必须 ≥ 0，D=0 时恢复无迁入模型。",defaults:[.000001,.0000002,0,.00001]},a:{name:"相互作用 aᵢⱼ",meaning:"无量纲；列物种 j 对行物种 i 的作用。aᵢⱼ > 0 为促进，< 0 为抑制，对角线固定为 −1。",defaults:[0,.18,-.6,.6]}};
function updateDistributionUI(resetTarget=false){let target=$("target").value,d=$("dist").value,info=targetInfo[target];Array.from($("dist").options).forEach(o=>{let valid=target==="a"?o.value!=="lognormal":o.value!=="mixed";o.hidden=!valid;o.disabled=!valid});if((target==="a"&&d==="lognormal")||(target!=="a"&&d==="mixed")){d="direct";$("dist").value=d}if(resetTarget){let q=info.defaults;$("center").value=q[0];$("spread").value=q[1];$("minVal").value=q[2];$("maxVal").value=q[3];d="direct";$("dist").value=d}let show=(id,on)=>$(id).classList.toggle("hidden",!on);show("centerField",d!=="uniform"&&d!=="direct");show("spreadField",d==="normal"||d==="lognormal"||d==="mixed");show("minField",d!=="direct");show("maxField",d!=="direct");show("posField",d==="mixed");show("randomBtn",d!=="direct");$("centerLabel").textContent=d==="mixed"?"绝对作用强度均值 μ":"算术均值 μ";$("spreadLabel").textContent=d==="lognormal"?"对数尺度标准差 σlog":"标准差 σ";$("minLabel").textContent=d==="mixed"?"最小绝对强度":"取值下限 L";$("maxLabel").textContent=d==="mixed"?"最大绝对强度":"取值上限 U";if(d==="mixed"&&num("minVal")<0)$("minVal").value=0;if((d==="lognormal"||target!=="a")&&num("minVal")<0)$("minVal").value=(target==="b0"||target==="m"||target==="d")?0:.0001;let text={direct:`不使用随机分布。请直接在下方参数表格中逐项输入或修改${info.name}；运行时读取表格中的当前数值。`,uniform:`X ~ U(L,U)：${info.name}在下限 L 与上限 U 之间等概率抽取；区间内各取值机会相同。`,normal:`X ~ N(μ,σ²)，并截断到 [L,U]：μ 控制分布中心，σ 控制离散程度，超出上下限的值被限制在边界。`,lognormal:`X 服从截断对数正态分布：输入的 μ 为目标算术均值，σlog 控制右偏程度；仅适用于严格非负参数。`,mixed:`先按“促进作用比例”决定正负号，再从截断正态分布抽取绝对作用强度；适合同时包含促进和抑制关系的矩阵。`}[d];$("distHelp").innerHTML=`<b>${info.name}</b>：${info.meaning}<br><b>当前输入方式</b>：${text}`}
function monoPrediction(r,m,x0,t){let q=r-m,L=q/r;return L/(1+(L/x0-1)*Math.exp(-q*t))}
function fitIntrinsicRate(s,t){if(!Number.isFinite(s.m)||s.m<0)throw Error(`${s.name} 的死亡率 m 必须为非负数`);let x0=s.b0/s.k,xt=s.bMid/s.k;if(!(x0>0&&x0<1&&xt>0&&xt<1))throw Error(`${s.name} 必须满足 0 < B₀、B(tₘ) < K`);let lo=s.m+1e-8,hi=Math.max(1,s.m+1),fLo=monoPrediction(lo,s.m,x0,t)-xt;if(fLo>0)throw Error(`${s.name} 的 B(tₘ) 过低，无法在 r > m 条件下拟合`);while(monoPrediction(hi,s.m,x0,t)<xt&&hi<1e4)hi*=2;if(hi>=1e4&&monoPrediction(hi,s.m,x0,t)<xt)throw Error(`${s.name} 无法拟合有限的增长率 r`);for(let n=0;n<80;n++){let mid=(lo+hi)/2;if(monoPrediction(mid,s.m,x0,t)<xt)lo=mid;else hi=mid}return(hi+lo)/2}
function fit(){sync();let t=Math.max(.01,num("midTime"));species=species.map(s=>({...s,g:+fitIntrinsicRate(s,t).toFixed(5)}));A=A.map((r,i)=>r.map((v,j)=>{if(i===j)return-1;let xi=pairs[i][j]/species[i].k,xj=pairs[j][i]/species[j].k,ci=1-species[i].m/species[i].g;return+(xj>1e-9?(xi-ci)/xj:0).toFixed(4)}));fitReady=true;renderInputs();setStatus("拟合完成：死亡率已作为独立损失项处理，并生成 r 与相互作用矩阵")}
function setMode(m){sync();mode=m;$("knownPanel").classList.toggle("hidden",m!=="known");$("fitPanel").classList.toggle("hidden",m!=="fit");$("knownTab").classList.toggle("active",m==="known");$("fitTab").classList.toggle("active",m==="fit");$("modeTitle").textContent=m==="known"?"已知参数设置":"实验数据拟合";renderInputs()}
function setStatus(t){$("status").textContent="● "+t}
function resizeModel(announce=true){sync();let requested=Math.round(num("nInput"));if(!Number.isFinite(requested)||requested<1||requested>20)throw Error("物种数量 N 必须为 1–20 的整数");if(requested===N)return false;let oldSpecies=species,oldA=A;N=requested;$("nInput").value=N;let defaults=makeSpecies(N),defaultA=makeA(N);species=Array.from({length:N},(_,i)=>oldSpecies[i]?{...defaults[i],...oldSpecies[i],d:Number.isFinite(oldSpecies[i].d)?oldSpecies[i].d:0}:defaults[i]);A=Array.from({length:N},(_,i)=>Array.from({length:N},(_,j)=>i===j?-1:(oldA[i]&&Number.isFinite(oldA[i][j])?oldA[i][j]:defaultA[i][j])));pairs=makePairs();fitReady=false;renderInputs();if(announce)setStatus(`已应用 N = ${N}，参数表和矩阵已安全重建`);return true}
function paintMatrixInput(el){let [i,j]=el.dataset.a.split(",").map(Number),v=Number(el.value);if(i===j||!A[i]||j>=A[i].length)return;A[i][j]=v;let alpha=Math.min(.75,Math.abs(v));el.parentElement.style.background=v>0?`rgba(23,63,103,${.08+alpha*.5})`:`rgba(216,109,91,${.08+alpha*.5})`}
function paintFittedMatrixInput(el){let [i,j]=el.dataset.fra.split(",").map(Number),v=Number(el.value);if(i===j||!A[i]||j>=A[i].length)return;A[i][j]=v;let alpha=Math.min(.75,Math.abs(v));el.parentElement.style.background=v>0?`rgba(23,63,103,${.08+alpha*.5})`:`rgba(216,109,91,${.08+alpha*.5})`}
async function exportCSV(){if(!result)simulate();let sp=species.map(s=>({...s})),mat=A.map(r=>r.slice()),params=[];sp.forEach((s,i)=>params.push([`S${i+1}_name`,s.name],[`S${i+1}_B0`,s.b0],[`S${i+1}_r`,s.g],[`S${i+1}_m`,s.m],[`S${i+1}_K`,s.k],[`S${i+1}_D`,s.d??0]));for(let i=0;i<N;i++)for(let j=0;j<N;j++)params.push([`a${i+1}_${j+1}`,mat[i][j]]);let head=["simulation_id","status","stable_time","time",...sp.map((s,i)=>`S${i+1}_${s.name}_B`),...params.map(q=>q[0])],rows=[head.map(csvCell).join(",")];result.pts.forEach(q=>rows.push([1,result.warning||"ok",result.stableTime==null?"":result.stableTime,q.t,...q.b,...params.map(p=>p[1])].map(csvCell).join(",")));let stamp=new Date().toISOString().replace(/[:.]/g,"-").slice(0,19),message=await saveCSV(rows.join("\n"),`glv_single_simulation_${stamp}.csv`);setStatus(`单次模拟 CSV 已生成；${message}`)}
function safely(fn){try{fn()}catch(e){console.error(e);setStatus("输入错误："+(e&&e.message?e.message:"请检查参数"));$("status").classList.add("warning")}}
async function safelyAsync(fn){try{await fn()}catch(e){console.error(e);if(e&&e.name==="AbortError"){setStatus("已取消保存 CSV");return}setStatus("输入错误："+(e&&e.message?e.message:"请检查参数"));$("status").classList.add("warning")}}
document.addEventListener("input",e=>{let el=e.target;if(el.matches("[data-a]"))paintMatrixInput(el);else if(el.matches("[data-s]")){let i=+el.dataset.s,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)}else if(el.matches("[data-exp]")){let i=+el.dataset.exp,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value);fitReady=false;$("fitResultPanel").classList.add("hidden")}else if(el.matches("[data-p]")){let [i,j]=el.dataset.p.split(",").map(Number);if(i!==j&&pairs[i]&&j<pairs[i].length)pairs[i][j]=Number(el.value);fitReady=false;$("fitResultPanel").classList.add("hidden")}else if(el.matches("[data-frs]")){let i=+el.dataset.frs,key=el.dataset.key;if(species[i])species[i][key]=key==="name"?el.value:Number(el.value)}else if(el.matches("[data-fra]"))paintFittedMatrixInput(el);if(el.id==="midTime"){fitReady=false;$("fitResultPanel").classList.add("hidden")}if(el.matches("input,select")){$("status").classList.remove("warning");setStatus(el.id==="nInput"?"物种数量已修改：点击“应用 N”或直接运行":"参数已修改：点击“运行模拟”更新结果")}});window.addEventListener("error",e=>setStatus("运行错误："+(e.message||"请检查输入参数")));
$("knownTab").onclick=()=>safely(()=>setMode("known"));$("fitTab").onclick=()=>safely(()=>setMode("fit"));$("runBtn").onclick=()=>safely(()=>{let changed=resizeModel(false);if(mode==="fit"&&!fitReady)throw Error("实验数据已修改，请先完成参数拟合");simulate();if(changed)setStatus(`已按 N = ${N} 重建模型并完成模拟`)});$("exportBtn").onclick=()=>safelyAsync(exportCSV);$("randomBtn").onclick=()=>safely(randomize);$("batchBtn").onclick=()=>safelyAsync(runBatch);$("fitBtn").onclick=()=>safely(fit);$("resizeBtn").onclick=()=>safely(()=>{let changed=resizeModel(true);if(changed&&mode==="known")simulate();else if(!changed)setStatus(`当前已是 N = ${N}`)});$("target").onchange=()=>updateDistributionUI(true);$("dist").onchange=()=>updateDistributionUI(false);
species=makeSpecies(N);A=makeA(N);pairs=makePairs();updateDistributionUI(false);renderInputs();safely(simulate);


(function makeSchematicTransparent(){
  var source=document.querySelector('.schematic-frame img');
  if(!source)return;

  function removeLightBackground(){
    if(source.dataset.transparentized==='1')return;
    source.dataset.transparentized='1';
    try{
      var canvas=document.createElement('canvas');
      canvas.width=source.naturalWidth;
      canvas.height=source.naturalHeight;
      var ctx=canvas.getContext('2d',{willReadFrequently:true});
      ctx.drawImage(source,0,0);
      var image=ctx.getImageData(0,0,canvas.width,canvas.height);
      var d=image.data;
      for(var i=0;i<d.length;i+=4){
        var light=Math.min(d[i],d[i+1],d[i+2]);
        if(light>=248)d[i+3]=0;
        else if(light>232)d[i+3]=Math.round(d[i+3]*(248-light)/16);
      }
      source.src=canvas.toDataURL('image/png');
    }catch(e){
      source.style.mixBlendMode='multiply';
    }
  }
  if(source.complete&&source.naturalWidth)removeLightBackground();
  else source.addEventListener('load',removeLightBackground,{once:true});
})();


(function addBatchSpeciesAssignment(){
  var speciesSection=document.getElementById('speciesTable').closest('section');
  var toolbar=document.createElement('div');
  toolbar.className='batch-assign';
  toolbar.innerHTML='<div class="batch-row"><label class="field"><span>批量设置参数</span><select id="batchKey"><option value="b0">初始生物量 B₀</option><option value="g">增长率 r</option><option value="m">死亡率 m</option><option value="k">容纳量 K</option><option value="d">迁入率 D</option></select></label><label class="field"><span>统一数值</span><input id="batchValue" type="number" value="1" step="0.01"></label><button class="small-btn" id="batchApply" type="button">应用到所选物种</button></div><div class="batch-species" id="batchSpecies"></div><div class="batch-hint">适用于多个物种共享同一参数值；应用后仍可在下方表格中逐项修改。</div>';
  speciesSection.insertBefore(toolbar,document.getElementById('speciesTable'));

  function renderBatchSpecies(){
    var box=document.getElementById('batchSpecies');
    box.innerHTML='<span>目标物种</span><button class="batch-link" id="batchAll" type="button">全选</button><button class="batch-link" id="batchNone" type="button">清空</button>'+species.map(function(s,i){return '<label class="batch-check"><input type="checkbox" data-batch-species="'+i+'" checked> S'+(i+1)+'</label>';}).join('');
    document.getElementById('batchAll').onclick=function(){box.querySelectorAll('[data-batch-species]').forEach(function(x){x.checked=true;});};
    document.getElementById('batchNone').onclick=function(){box.querySelectorAll('[data-batch-species]').forEach(function(x){x.checked=false;});};
  }
  var originalRenderInputs=renderInputs;
  renderInputs=function(){originalRenderInputs();renderBatchSpecies();};
  renderBatchSpecies();

  document.getElementById('batchKey').onchange=function(){
    var defaults={b0:[0.1,0.01],g:[0.6,0.01],m:[0.05,0.01],k:[1,0.1],d:[0.000001,0.000001]},q=defaults[this.value],input=document.getElementById('batchValue');
    input.value=q[0];input.step=q[1];
  };
  document.getElementById('batchApply').onclick=function(){safely(function(){
    sync();
    var key=document.getElementById('batchKey').value,value=Number(document.getElementById('batchValue').value);
    if(!Number.isFinite(value))throw Error('请输入有效的批量参数数值');
    if((key==='b0'||key==='m'||key==='d')&&value<0)throw Error((key==='b0'?'B₀':key==='m'?'m':'D')+' 必须为非负数');
    if((key==='g'||key==='k')&&value<=0)throw Error((key==='g'?'r':'K')+' 必须大于 0');
    var chosen=Array.from(document.querySelectorAll('[data-batch-species]:checked')).map(function(x){return Number(x.dataset.batchSpecies);});
    if(!chosen.length)throw Error('请至少选择一个目标物种');
    var trial=species.map(function(s){return Object.assign({},s);});
    chosen.forEach(function(i){if(trial[i])trial[i][key]=value;});
    trial.forEach(function(s){if(!(s.g>s.m))throw Error(s.name+' 不满足 r > m；请同时调整增长率或死亡率');});
    species=trial;
    renderInputs();
    setStatus('已将 '+({b0:'B₀',g:'r',m:'m',k:'K',d:'D'}[key])+' = '+value+' 应用到 '+chosen.length+' 个物种');
  });};
})();


(function(){
  var inputCard=document.querySelector('.input-card'),fitPanel=document.getElementById('fitPanel');
  var monte=document.createElement('div');
  monte.id='montePanel';monte.className='hidden monte-panel';
  monte.innerHTML='<div class="monte-intro"><b>独立随机参数模型：</b>本页面的设置与“已知参数模型”和“从实验数据拟合”完全独立。每次重复都会依据下表生成整套 B₀、r、m、K、D 和相互作用矩阵 A。选择随机分布的参数会在每次重复中重新抽样；选择“固定值”的参数在下方按物种或作用方向逐项设置。</div><section class="subcard"><div class="subhead"><h3>参数生成方式表</h3><span>每类参数独立设置</span></div><div class="scroll" style="max-height:none"><table class="mc-table"><thead><tr><th>参数</th><th>生成方式</th><th>分布中心 μ</th><th>标准差 σ</th><th>下限 L</th><th>上限 U</th><th>促进比例</th><th>参数意义</th></tr></thead><tbody id="mcRows"></tbody></table></div></section><section id="mcFixedCard" class="subcard mc-fixed-card hidden"><div class="subhead"><h3>逐对象固定值</h3><span>固定参数在全部重复中保持不变，可为不同物种设置不同数值</span></div><div id="mcFixedEditors" class="mc-fixed-editors"></div></section>';
  inputCard.insertBefore(monte,fitPanel.nextSibling);
  var oldBatch=document.querySelector('#knownPanel .batch-card');
  monte.appendChild(oldBatch);
  oldBatch.querySelector('.batch-copy p').textContent='每次依据本页参数生成方式表独立生成整套模型参数。CSV 保存每次实际抽取的完整参数、稳定状态和全部时间序列。';
  oldBatch.querySelector('.batch-summary').textContent='设置各参数的生成方式后开始；浏览器将提示选择 CSV 保存地址。';

  var defs={
    b0:{label:'初始生物量 B₀',dist:'lognormal',c:.08,s:.25,lo:.01,hi:.2,p:'—',meaning:'模拟起始时各物种的实际生物量，单位与 K 一致。'},
    g:{label:'增长率 r',dist:'normal',c:.6,s:.1,lo:.15,hi:1.2,p:'—',meaning:'增长项的内禀增长率，单位为时间⁻¹，须满足 r > m。'},
    m:{label:'死亡率 m',dist:'normal',c:.05,s:.015,lo:0,hi:.15,p:'—',meaning:'独立损失项 −mᵢxᵢ 的死亡率，单位为时间⁻¹。'},
    k:{label:'容纳量 K',dist:'lognormal',c:1,s:.2,lo:.2,hi:2,p:'—',meaning:'无死亡时的单培养容纳量及生物量无量纲化尺度。'},
    d:{label:'迁入率 D',dist:'fixed',c:.000001,s:.0000002,lo:0,hi:.00001,p:'—',meaning:'外部物种库的持续加性输入，单位为归一化生物量·时间⁻¹。'},
    a:{label:'相互作用 aᵢⱼ',dist:'mixed',c:.18,s:.08,lo:0,hi:.6,p:35,meaning:'物种 j 对物种 i 的无量纲作用；对角线固定为 −1。'}
  };
  var fixedValues={b0:[],g:[],m:[],k:[],d:[],a:[]};
  function captureFixedValues(){document.querySelectorAll('[data-mcfix]').forEach(function(el){var key=el.dataset.mcfix,v=Number(el.value);if(key==='a'){var ij=el.dataset.index.split(',').map(Number);if(!fixedValues.a[ij[0]])fixedValues.a[ij[0]]=[];fixedValues.a[ij[0]][ij[1]]=v;}else fixedValues[key][Number(el.dataset.index)]=v;});}
  function ensureFixedValues(){['b0','g','m','k','d'].forEach(function(key){for(var i=0;i<N;i++)if(!Number.isFinite(fixedValues[key][i]))fixedValues[key][i]=defs[key].c;fixedValues[key].length=N;});for(var i=0;i<N;i++){if(!Array.isArray(fixedValues.a[i]))fixedValues.a[i]=[];for(var j=0;j<N;j++)if(!Number.isFinite(fixedValues.a[i][j]))fixedValues.a[i][j]=i===j?-1:defs.a.c;fixedValues.a[i].length=N;}fixedValues.a.length=N;}
  function renderFixedEditors(){captureFixedValues();ensureFixedValues();var selected={};document.querySelectorAll('[data-mc]').forEach(function(row){selected[row.dataset.mc]=row.querySelector('[data-mcf="dist"]').value==='fixed';});var keys=['b0','g','m','k','d'].filter(function(key){return selected[key];}),html='';if(keys.length){html+='<div class="mc-fixed-block"><h4>物种参数</h4><div class="scroll"><table><thead><tr><th>物种</th>'+keys.map(function(key){return '<th>'+defs[key].label+'</th>';}).join('')+'</tr></thead><tbody>'+Array.from({length:N},function(_,i){return '<tr><th>S'+(i+1)+'</th>'+keys.map(function(key){return '<td><input type="number" data-mcfix="'+key+'" data-index="'+i+'" value="'+fixedValues[key][i]+'" step="'+(key==='d'?'0.000001':'0.01')+'"></td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div></div>';}
    if(selected.a){html+='<div class="mc-fixed-block"><h4>固定相互作用矩阵 A <small>列物种 j → 行物种 i；对角线固定为 −1</small></h4><div class="scroll"><table class="matrix"><thead><tr><th></th>'+Array.from({length:N},function(_,j){return '<th>S'+(j+1)+'</th>';}).join('')+'</tr></thead><tbody>'+Array.from({length:N},function(_,i){return '<tr><th>S'+(i+1)+'</th>'+Array.from({length:N},function(_,j){return '<td class="'+(i===j?'diag':'')+'"><input type="number" data-mcfix="a" data-index="'+i+','+j+'" value="'+(i===j?-1:fixedValues.a[i][j])+'" step="0.01" '+(i===j?'readonly':'')+'></td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div></div>';}
    document.getElementById('mcFixedEditors').innerHTML=html;document.getElementById('mcFixedCard').classList.toggle('hidden',!html);}
  function options(key,chosen){var vals=key==='a'?[['fixed','固定值'],['uniform','均匀分布'],['normal','截断正态'],['mixed','促进/抑制混合正态']]:[['fixed','固定值'],['uniform','均匀分布'],['normal','截断正态'],['lognormal','截断对数正态']];return vals.map(function(q){return '<option value="'+q[0]+'" '+(q[0]===chosen?'selected':'')+'>'+q[1]+'</option>';}).join('');}
  function renderMonteRows(){document.getElementById('mcRows').innerHTML=Object.keys(defs).map(function(key){var q=defs[key];return '<tr data-mc="'+key+'"><th>'+q.label+'</th><td><select data-mcf="dist">'+options(key,q.dist)+'</select></td><td><input type="number" data-mcf="c" value="'+q.c+'" step="0.01"></td><td><input type="number" data-mcf="s" value="'+q.s+'" min="0" step="0.01"></td><td><input type="number" data-mcf="lo" value="'+q.lo+'" step="0.01"></td><td><input type="number" data-mcf="hi" value="'+q.hi+'" step="0.01"></td><td>'+(key==='a'?'<input type="number" data-mcf="p" value="'+q.p+'" min="0" max="100">':'—')+'</td><td class="mc-meaning">'+q.meaning+'</td></tr>';}).join('');updateMonteRows();}
  function updateMonteRows(){document.querySelectorAll('[data-mc]').forEach(function(row){var d=row.querySelector('[data-mcf="dist"]').value;['c','s','lo','hi'].forEach(function(f){var el=row.querySelector('[data-mcf="'+f+'"]'),on=f==='c'?(d!=='uniform'&&d!=='fixed'):f==='s'?(d==='normal'||d==='lognormal'||d==='mixed'):(d!=='fixed');el.disabled=!on;el.parentElement.classList.toggle('na',!on);});var p=row.querySelector('[data-mcf="p"]');if(p){p.disabled=d!=='mixed';p.parentElement.classList.toggle('na',d!=='mixed');}});renderFixedEditors();}
  renderMonteRows();
  document.getElementById('mcRows').addEventListener('change',function(e){if(e.target.matches('[data-mcf="dist"]'))updateMonteRows();});

  function monteSettings(){captureFixedValues();var out={};document.querySelectorAll('[data-mc]').forEach(function(row){var key=row.dataset.mc,get=function(f){var x=row.querySelector('[data-mcf="'+f+'"]');return x?Number(x.value):NaN;};out[key]={d:row.querySelector('[data-mcf="dist"]').value,c:get('c'),s:get('s'),lo:get('lo'),hi:get('hi'),pct:get('p'),fixed:key==='a'?fixedValues.a.map(function(r){return r.slice();}):fixedValues[key].slice()};var q=out[key];if(q.d!=='fixed'&&(!(q.lo<q.hi)))throw Error(defs[key].label+' 的下限必须小于上限');if((key==='b0'||key==='m'||key==='d')&&q.d!=='fixed'&&q.lo<0)throw Error(defs[key].label+' 的下限必须为非负数');if(['normal','lognormal','mixed'].indexOf(q.d)>=0&&(!(q.s>=0)))throw Error(defs[key].label+' 的标准差必须为非负数');if(key==='a'&&q.d==='mixed'&&(!(q.pct>=0&&q.pct<=100)))throw Error('相互作用促进比例必须为 0–100%');if(q.d==='fixed'){var vals=key==='a'?q.fixed.flat():q.fixed;if(vals.some(function(v){return !Number.isFinite(v);})){throw Error(defs[key].label+' 的逐项固定值必须为有效数字');}if((key==='b0'||key==='m'||key==='d')&&vals.some(function(v){return v<0;}))throw Error(defs[key].label+' 的逐项固定值必须为非负数');}});return out;}
  function drawOne(q,key,i,j){if(q.d==='fixed')return key==='a'?q.fixed[i][j]:q.fixed[i];if(key==='a'&&q.d==='mixed'){var sign=Math.random()*100<q.pct?1:-1,mag=sampleDist('normal',Math.abs(q.c),q.s,Math.max(0,q.lo),Math.max(0,q.hi));return sign*Math.abs(mag);}return sampleDist(q.d,q.c,q.s,q.lo,q.hi);}
  function fullRandomModel(cfg){for(var attempt=0;attempt<300;attempt++){var sp=Array.from({length:N},function(_,i){return{name:'Species '+(i+1),b0:Math.max(0,drawOne(cfg.b0,'b0',i)),g:Math.max(.000001,drawOne(cfg.g,'g',i)),m:Math.max(0,drawOne(cfg.m,'m',i)),k:Math.max(.000001,drawOne(cfg.k,'k',i)),d:Math.max(0,drawOne(cfg.d,'d',i))};});if(sp.some(function(s){return !(s.g>s.m);}))continue;var mat=Array.from({length:N},function(_,i){return Array.from({length:N},function(_,j){return i===j?-1:drawOne(cfg.a,'a',i,j);});});return{sp:sp,mat:mat};}throw Error('当前 r 与 m 设置难以满足每个物种的 r > m，请检查逐项固定值或调整随机分布');}
  var baseResizeModel=resizeModel;
  resizeModel=function(announce){captureFixedValues();var changed=baseResizeModel(announce);if(changed)renderFixedEditors();return changed;};
  runBatch=async function(){if(mode!=='monte')throw Error('请切换到“多次随机模拟”页面');resizeModel(false);var cfg=monteSettings(),count=Math.round(num('batchCount'));if(!Number.isFinite(count)||count<2||count>1000)throw Error('随机模拟次数必须为 2–1000 的整数');var button=$('batchBtn'),progress=$('batchProgress'),summary=$('batchSummary'),records=[],unbounded=0;button.disabled=true;button.textContent='模拟中…';try{for(var run=1;run<=count;run++){var model=fullRandomModel(cfg),sim=simulateModel(model.sp,model.mat),param=[];model.sp.forEach(function(s,i){param.push(['S'+(i+1)+'_name',s.name],['S'+(i+1)+'_B0',s.b0],['S'+(i+1)+'_r',s.g],['S'+(i+1)+'_m',s.m],['S'+(i+1)+'_K',s.k],['S'+(i+1)+'_D',s.d]);});for(var i=0;i<N;i++)for(var j=0;j<N;j++)param.push(['a'+(i+1)+'_'+(j+1),model.mat[i][j]]);if(sim.warning)unbounded++;records.push({run:run,sim:sim,param:param});progress.style.width=(run/count*100)+'%';summary.textContent='正在模拟：'+run+' / '+count;if(run%5===0)await new Promise(function(resolve){setTimeout(resolve,0);});}var names=records[0].param.map(function(q){return q[0];}),head=['run','status','stable_time','time'].concat(Array.from({length:N},function(_,i){return 'S'+(i+1)+'_B';}),names),rows=[head.map(csvCell).join(',')];records.forEach(function(rec){rec.sim.pts.forEach(function(pt){rows.push([rec.run,rec.sim.warning||'ok',rec.sim.stableTime==null?'':rec.sim.stableTime,pt.t].concat(pt.b,rec.param.map(function(q){return q[1];})).map(csvCell).join(','));});});var stamp=new Date().toISOString().replace(/[:.]/g,'-').slice(0,19),message=await saveCSV(rows.join('\n'),'glv_random_simulations_'+count+'_'+stamp+'.csv');summary.textContent='完成 '+count+' 次模拟（无界增长 '+unbounded+' 次）；'+message;setStatus('多次随机模拟完成：'+count+' 次，CSV 已生成');}finally{button.disabled=false;button.textContent='运行并保存 CSV';}};
  document.getElementById('batchBtn').onclick=function(){safelyAsync(runBatch);};

  var baseSync=sync;
  sync=function(){if(mode!=='monte')baseSync();};
  var baseSetMode=setMode;
  setMode=function(m){if(m==='monte'){sync();mode=m;$('knownPanel').classList.add('hidden');$('fitPanel').classList.add('hidden');$('montePanel').classList.remove('hidden');$('knownTab').classList.remove('active');$('fitTab').classList.remove('active');$('monteTab').classList.add('active');$('modeTitle').textContent='多次随机模拟参数设置';$('runBtn').classList.add('hidden');$('exportBtn').classList.add('hidden');renderInputs();renderFixedEditors();}else{captureFixedValues();baseSetMode(m);$('montePanel').classList.add('hidden');$('monteTab').classList.remove('active');$('runBtn').classList.remove('hidden');$('exportBtn').classList.remove('hidden');}};
  document.getElementById('monteTab').onclick=function(){safely(function(){setMode('monte');});};
  document.querySelector('header .formula').textContent='dxᵢ/dt = rᵢxᵢ(1 − xᵢ + Σⱼ≠ᵢ aᵢⱼxⱼ) − mᵢxᵢ + Dᵢ';
})();


document.querySelector(".footer").insertAdjacentHTML("beforebegin", `<section class="methodology" aria-labelledby="methodologyTitle"><article class="card methodology-card"><div class="methodology-head"><div><span class="eyebrow">METHODS &amp; ALGORITHMS</span><h2 id="methodologyTitle">制作方法、模型与求解说明</h2></div><p class="methodology-intro">本网页为无服务器依赖的单文件 HTML 应用，界面、随机数生成、参数拟合、常微分方程求解、绘图及 CSV 导出均由浏览器端 JavaScript 完成。输入数据不会上传至服务器。</p></div><div class="method-grid"><section class="method-block"><h3>1. 数学模型</h3><p>采用带独立死亡项的广义 Lotka–Volterra（gLV）模型。无量纲丰度为 <i>x</i><sub>i</sub>=<i>B</i><sub>i</sub>/<i>K</i><sub>i</sub>：</p><div class="method-equation">dx<sub>i</sub>/dt = r<sub>i</sub>x<sub>i</sub>(1 − x<sub>i</sub> + Σ<sub>j≠i</sub>a<sub>ij</sub>x<sub>j</sub>) − m<sub>i</sub>x<sub>i</sub></div><ul><li><i>B</i><sub>0,i</sub>：初始实际生物量；<i>r</i><sub>i</sub>：内禀增长率；<i>m</i><sub>i</sub>：独立死亡率。</li><li><i>K</i><sub>i</sub>：生物量尺度及无死亡时的单培养逻辑斯蒂上限；<i>a</i><sub>ij</sub>：物种 <i>j</i> 对物种 <i>i</i> 的作用。</li><li><i>a</i><sub>ij</sub>&gt;0 表示促进，&lt;0 表示抑制；程序固定 <i>a</i><sub>ii</sub>=−1。</li></ul></section><section class="method-block"><h3>2. 生物量与平衡点</h3><p>计算从 <i>x</i><sub>i</sub>(0)=<i>B</i><sub>0,i</sub>/<i>K</i><sub>i</sub> 开始，输出时恢复为 <i>B</i><sub>i</sub>(t)=<i>K</i><sub>i</sub><i>x</i><sub>i</sub>(t)。死亡项不与物种相互作用耦合。</p><div class="method-equation">B<sub>i</sub>* = K<sub>i</sub>(1 − m<sub>i</sub>/r<sub>i</sub>)　（单培养，r<sub>i</sub>&gt;m<sub>i</sub>）</div><p>因此 <i>K</i><sub>i</sub> 不是加入死亡率后的单培养观测终点，也不是共培养中的硬上限；促进作用可使共培养生物量超过 <i>K</i><sub>i</sub>。</p></section><section class="method-block"><h3>3. 数值积分与判定</h3><p>常微分方程使用经典四阶 Runge–Kutta（RK4）显式积分。内部步长依据输出间隔和总模拟时间自动取较小值；负丰度在数值误差下截为 0。</p><div class="method-equation">max<sub>i</sub>|dx<sub>i</sub>/dt| / max(1, x<sub>1</sub>,…,x<sub>N</sub>) &lt; ε</div><p>上式连续满足一个观察窗口时记录稳定时刻，ε 可在结果区设置。若任一无量纲丰度非有限或达到程序阈值 10<sup>6</sup>，则标记为“无界增长”。</p></section><section class="method-block"><h3>4. 实验数据拟合</h3><p>先利用各物种单培养的 <i>B</i><sub>0</sub>、中间时刻 <i>B</i>(<i>t</i><sub>m</sub>)、<i>K</i> 和已知 <i>m</i>，通过二分法反演满足单培养解析轨迹的 <i>r</i>。随后由双培养稳定终点计算方向性作用：</p><div class="method-equation">a<sub>ij</sub> = [x<sub>i</sub>* − (1 − m<sub>i</sub>/r<sub>i</sub>)] / x<sub>j</sub>*</div><p>其中 <i>x</i><sub>i</sub>*=<i>C</i><sub>ij</sub>/<i>K</i><sub>i</sub>，<i>x</i><sub>j</sub>*=<i>C</i><sub>ji</sub>/<i>K</i><sub>j</sub>。该反演假设输入双培养终点近似稳定，且成对估计的系数可用于多物种体系。</p></section><section class="method-block"><h3>5. 多次随机模拟</h3><p>第三个标签页为 <i>B</i><sub>0</sub>、<i>r</i>、<i>m</i>、<i>K</i> 和非对角 <i>a</i><sub>ij</sub> 分别设置独立生成规则。每次重复均重新生成完整参数组，再独立运行一次模型。</p><ul><li>支持固定值、均匀分布、截断正态分布和截断对数正态分布。</li><li>相互作用还支持按促进比例决定符号的促进/抑制混合正态分布。</li><li>抽样自动检查参数范围及 <i>r</i><sub>i</sub>&gt;<i>m</i><sub>i</sub>；不合格组合会重新抽样。</li></ul></section><section class="method-block"><h3>6. 数据输出与复现</h3><p>单次和多次模拟均可导出 UTF-8 CSV。每一行包括模拟编号、状态、稳定时刻、时间点及各物种实际生物量；同一模拟实际使用的全部 <i>B</i><sub>0</sub>、<i>r</i>、<i>m</i>、<i>K</i> 和 <i>A</i> 矩阵也一并写入。</p><p>导出的 CSV 将通过浏览器下载并保存到浏览器设置的下载目录；如浏览器启用了“下载前询问保存位置”，则可在下载时选择保存位置。随机模拟当前未设置固定随机种子，因此每次运行可能得到不同结果。</p></section><section class="method-block method-caveat"><h3>适用范围与注意事项</h3><p>本工具用于 gLV 模型的教学、探索性分析和实验设计，不替代针对具体数据的严格统计推断。模型假设参数在模拟期间恒定、作用成对可加、环境条件不变，且未显式描述资源、空间结构、时滞、进化或测量误差。强正反馈可能导致无界增长；这既可能反映参数不合理，也可能提示简单 gLV 模型缺少资源限制。实验拟合的可靠性取决于单培养曲线、死亡率、容纳量及双培养稳定终点的测量质量，建议结合重复实验、置信区间和独立数据验证。</p></section></div><details><summary>实现与版本说明</summary><p>本页采用原生 HTML、CSS、Canvas 与 JavaScript 构建，无外部代码库和联网依赖。随机数由浏览器 <code>Math.random()</code> 提供，正态随机变量通过 Box–Muller 变换生成；截断实现为将超界抽样值限制到给定边界。图形由 Canvas 即时绘制，所有运算在用户设备本地完成。</p></details></article></section>`);
document.querySelector(".method-grid .method-equation").innerHTML='dx<sub>i</sub>/dt = r<sub>i</sub>x<sub>i</sub>(1 − x<sub>i</sub> + Σ<sub>j≠i</sub>a<sub>ij</sub>x<sub>j</sub>) − m<sub>i</sub>x<sub>i</sub> + D<sub>i</sub>';
document.querySelector(".method-grid .method-block ul").insertAdjacentHTML("beforeend",'<li><i>D</i><sub>i</sub>：外部物种库对物种 <i>i</i> 的持续迁入率；为加性输入，单位为归一化生物量·时间<sup>−1</sup>，设为 0 时恢复原模型。</li>');
document.querySelectorAll(".method-grid .method-block")[3].insertAdjacentHTML("beforeend",'<p><b>说明：</b>上述实验数据反演假设 <i>D</i><sub>i</sub>=0；拟合完成后可另行设置迁入率用于预测模拟。</p>');
document.querySelectorAll(".method-grid .method-block")[4].querySelector("p").innerHTML='第三个标签页为 <i>B</i><sub>0</sub>、<i>r</i>、<i>m</i>、<i>K</i>、<i>D</i> 和非对角 <i>a</i><sub>ij</sub> 分别设置独立生成规则。每次重复均重新生成完整参数组，再独立运行一次模型。';
document.querySelectorAll(".method-grid .method-block")[5].querySelector("p").innerHTML='单次和多次模拟均可导出 UTF-8 CSV。每一行包括模拟编号、状态、稳定时刻、时间点及各物种实际生物量；同一模拟实际使用的全部 <i>B</i><sub>0</sub>、<i>r</i>、<i>m</i>、<i>K</i>、<i>D</i> 和 <i>A</i> 矩阵也一并写入。';
